/*
 * Pre-recorded character voices: one MP3 per story character, generated by `gen.html` (which
 * runs the app's own Piper worker) and shipped in `static/voices/`. Each file is named after the
 * character id and speaks that character's reference sentence, so the browser never has to clone
 * a voice at runtime — it just plays the clip.
 *
 * The clips are loaded lazily and cached as AudioBuffers. A character that has no clip falls back
 * to the browser's own speechSynthesis (see StoryMode.svelte), so a missing recording never breaks
 * the story, it just sounds less natural.
 */
import { settings } from '#lib/state/settings.svelte.js';

type VoiceMeta = Record<string, { model: string; speaker: number; rate: number; text: string; bytes: number }>;

let meta: VoiceMeta | null = null;
const buffers = new Map<string, AudioBuffer>();
let context: AudioContext | null = null;

function audio() {
  context ??= new AudioContext();
  if (context.state === 'suspended') void context.resume();
  return context;
}

async function loadMeta() {
  if (meta) return meta;
  try {
    const response = await fetch('/voices/voices-meta.json', { cache: 'no-store' });
    if (!response.ok) return {};
    meta = await response.json() as VoiceMeta;
  } catch {
    meta = {};
  }
  return meta;
}

/** True when pre-recorded character clips are available for the current language. */
export function recordedVoicesSupported() {
  return typeof window !== 'undefined' && 'AudioContext' in window;
}

/** Loads a character's clip into an AudioBuffer (cached). Returns null if none exists. */
export async function loadRecordedVoice(character: string): Promise<AudioBuffer | null> {
  if (!recordedVoicesSupported()) return null;
  const cached = buffers.get(character);
  if (cached) return cached;
  await loadMeta();
  if (!meta || !meta[character]) return null;
  try {
    const response = await fetch(`/voices/${character}.mp3`, { cache: 'force-cache' });
    if (!response.ok) return null;
    const arrayBuffer = await response.arrayBuffer();
    const buffer = await audio().decodeAudioData(arrayBuffer);
    buffers.set(character, buffer);
    return buffer;
  } catch {
    return null;
  }
}

export type RecordedClip = { buffer: AudioBuffer; playbackRate: number; volume: number };

/** Plays a recorded clip; `done` resolves when it finishes or is stopped. */
export function playRecorded(clip: RecordedClip, volume = 1) {
  const output = audio();
  const source = output.createBufferSource();
  const gain = output.createGain();
  source.buffer = clip.buffer;
  source.playbackRate.value = clip.playbackRate;
  gain.gain.value = clip.volume * volume;
  source.connect(gain).connect(output.destination);
  const done = new Promise<void>((resolve) => source.addEventListener('ended', () => resolve()));
  const seconds = clip.buffer.duration / clip.playbackRate;
  const startedAt = output.currentTime;
  source.start();
  return {
    done,
    seconds,
    position: () => Math.max(0, Math.min(seconds, output.currentTime - startedAt)),
    stop: () => { try { source.stop(); } catch { /* already over */ } }
  };
}

/** Whether the story should use pre-recorded clips instead of synthesizing on the fly. */
export function useRecordedVoices() {
  return settings.voiceQuality === 'natural' && recordedVoicesSupported();
}